@@ -0,0 +1,95 @@
+/**
+ * Idempotent backfill: applies extractLastCargoesFromBody to parsedVessels
+ * where lastCargoes is null/empty, using the matched email body.
+ *
+ * Usage:
+ *   npx tsx scripts/backfill-lastcargoes.ts
+ *
+ * Env:
+ *   SESSIONS_DB_PATH — path to sessions.db (default: data/sessions.db)
+ */
+
+import Database from 'better-sqlite3';
+import * as path from 'path';
+import { extractLastCargoesFromBody } from '../lib/parsing/lastcargoes-fallback';
+
+interface EmailRow {
+  id: string;
+  body: string;
+  snippet: string;
+}
+
+interface ParsedVesselRow {
+  emailId: string;
+  itemIndex: number;
+  lastCargoes: string | null;
+  [key: string]: unknown;
+}
+
+interface SessionRow {
+  id: string;
+  data: string;
+}
+
+interface SessionData {
+  emails?: EmailRow[];
+  parsedVessels?: ParsedVesselRow[];
+  [key: string]: unknown;
+}
+
+const dbPath = process.env.SESSIONS_DB_PATH ?? path.join(process.cwd(), 'data', 'sessions.db');
+
+console.log(`[backfill-lastcargoes] Opening DB: ${dbPath}`);
+const db = new Database(dbPath, { readonly: false });
+
+const sessions = db.prepare<[], SessionRow>('SELECT id, data FROM sessions').all();
+console.log(`[backfill-lastcargoes] Found ${sessions.length} session(s)`);
+
+let totalSessionsUpdated = 0;
+let totalVesselsUpdated = 0;
+
+for (const session of sessions) {
+  let sessionData: SessionData;
+  try {
+    sessionData = JSON.parse(session.data) as SessionData;
+  } catch {
+    console.warn(`[backfill-lastcargoes] Session ${session.id}: failed to parse JSON, skipping`);
+    continue;
+  }
+
+  const emails: EmailRow[] = sessionData.emails ?? [];
+  const parsedVessels: ParsedVesselRow[] = sessionData.parsedVessels ?? [];
+
+  // Build emailId → body lookup
+  const emailBodyMap = new Map<string, string>();
+  for (const email of emails) {
+    emailBodyMap.set(email.id, email.body || email.snippet || '');
+  }
+
+  let updatedInSession = 0;
+
+  for (const vessel of parsedVessels) {
+    // Skip vessels that already have lastCargoes
+    if (vessel.lastCargoes && vessel.lastCargoes.trim().length > 0) continue;
+
+    const body = emailBodyMap.get(vessel.emailId);
+    if (!body) continue;
+
+    const extracted = extractLastCargoesFromBody(body);
+    if (!extracted) continue;
+
+    vessel.lastCargoes = extracted;
+    updatedInSession++;
+    totalVesselsUpdated++;
+  }
+
+  if (updatedInSession > 0) {
+    const newData = JSON.stringify(sessionData);
+    db.prepare('UPDATE sessions SET data = ? WHERE id = ?').run(newData, session.id);
+    console.log(`[backfill-lastcargoes] Session ${session.id}: updated ${updatedInSession} vessel(s)`);
+    totalSessionsUpdated++;
+  }
+}
+
+console.log(`[backfill-lastcargoes] Done. Sessions updated: ${totalSessionsUpdated}, vessels updated: ${totalVesselsUpdated}`);
+db.close();
